excels.excel:

EXPORT WITH SHEET="客户退货原因分析表", HEADER=true,
    MAPPING={"a":"退货原因","b":"退货数量","c":"退货金额","d":"数量占比","e":"责任部门"},
    FORMAT={"b":"#,##0","c":"#,##0.00","d":"0.00%"},
    FORMULAS={
        D2:'B2/B7',D3:'B3/B7',D4:'B4/B7',D5:'B5/B7',D6:'B6/B7',
        B7:'SUM(B2:B6)',C7:'SUM(C2:C6)',D7:'SUM(D2:D6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        D4:{color:red,bold:true}
    }
